class Solution:
    def lastRemaining(self, n: int) -> int:
        arr = list(range(1, n + 1))
        left = True
        while len(arr) > 1:
            arr = arr[1::2] if left else arr[-2::-2][::-1]
            left = not left
        return arr[0]

