class Solution {
public:
    int lastRemaining(int n) {
        vector<int> arr(n);
        iota(arr.begin(), arr.end(), 1);
        bool left = true;
        while (arr.size() > 1) {
            vector<int> nxt;
            if (left) {
                for (int i = 1; i < (int)arr.size(); i += 2) nxt.push_back(arr[i]);
            } else {
                for (int i = (int)arr.size() - 2; i >= 0; i -= 2) nxt.push_back(arr[i]);
                reverse(nxt.begin(), nxt.end());
            }
            arr.swap(nxt);
            left = !left;
        }
        return arr[0];
    }
};

