class Solution {
    public int lastRemaining(int n) {
        List<Integer> arr = new ArrayList<>();
        for (int i = 1; i <= n; i++) arr.add(i);
        boolean left = true;
        while (arr.size() > 1) {
            List<Integer> nxt = new ArrayList<>();
            if (left) {
                for (int i = 1; i < arr.size(); i += 2) nxt.add(arr.get(i));
            } else {
                for (int i = arr.size() - 2; i >= 0; i -= 2) nxt.add(arr.get(i));
                Collections.reverse(nxt);
            }
            arr = nxt;
            left = !left;
        }
        return arr.get(0);
    }
}

