    int lastRemaining(int n) {
        long long head = 1, step = 1;
        int remaining = n;
        bool left = true;
        while (remaining > 1) {
            if (left || remaining % 2 == 1) head += step;
            remaining /= 2;
            step *= 2;
            left = !left;
        }
        return (int)head;
    }
};

